import{_ as t,c as a,o as n,ag as r}from"./chunks/framework.Vyheyqg9.js";const u=JSON.parse('{"title":"Test and debug with an assistant","description":"","frontmatter":{},"headers":[],"relativePath":"ai-assisted-engineering/testing-debugging.md","filePath":"ai-assisted-engineering/testing-debugging.md"}'),s={name:"ai-assisted-engineering/testing-debugging.md"};function i(o,e,d,l,c,h){return n(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="_4-test-and-debug-with-an-assistant" tabindex="-1">Test and debug with an assistant <a class="header-anchor" href="#_4-test-and-debug-with-an-assistant" aria-label="Permalink to “Test and debug with an assistant”">​</a></h1><p>An assistant can write a plausible test that passes while checking the wrong thing. Begin with expected behavior from the task, then use generated checks as proposals to inspect.</p><p>For the catalogue, input immutability, stable ordering and preserving zero are separate requirements. One “returns an array” test does not cover them.</p><h2 id="classify-a-failure-before-changing-code" tabindex="-1"><span class="hub-section-number">1 </span>Classify a failure before changing code <a class="header-anchor" href="#classify-a-failure-before-changing-code" aria-label="Permalink to “1 Classify a failure before changing code”">​</a></h2><table tabindex="0"><thead><tr><th>Failure</th><th>First investigation</th></tr></thead><tbody><tr><td>Compiler cannot find a module</td><td>Working directory, imports, lockfile and build output</td></tr><tr><td>Assertion differs</td><td>Expected contract, actual input and observed result</td></tr><tr><td>Local HTTP listen is denied</td><td>Environment permission; do not rewrite correct request logic</td></tr><tr><td>Timeout/open handle</td><td>Unclosed server, connection, timer or pending async work</td></tr><tr><td>Provider unavailable</td><td>Configuration, model/endpoint access and transport limits</td></tr><tr><td>Flaky generated text</td><td>Task rubric and model variability; avoid exact prose snapshots</td></tr></tbody></table><p>Give the assistant the command, exit result and relevant error. Ask for a cause supported by the evidence and one check that distinguishes alternatives. Do not send secret-bearing environment dumps or full private logs.</p><h2 id="challenge-the-tests" tabindex="-1"><span class="hub-section-number">2 </span>Challenge the tests <a class="header-anchor" href="#challenge-the-tests" aria-label="Permalink to “2 Challenge the tests”">​</a></h2><p>In a disposable learner copy, deliberately replace the undefined-only default with <code>limit || 10</code>. The zero-limit check should fail. Replace a copied sort with an in-place sort on mutable input: the ownership regression should fail. Restore only your owned experiment after recording results.</p><p>These fault challenges ask whether checks detect the important behavior. They do not require exhaustively mutating every line or testing implementation details. Do not alter protected Autocode <code>src/tests</code>; add permitted independent checks elsewhere when the template allows it.</p><h2 id="verify-in-layers" tabindex="-1"><span class="hub-section-number">3 </span>Verify in layers <a class="header-anchor" href="#verify-in-layers" aria-label="Permalink to “3 Verify in layers”">​</a></h2><p>Start with a pure function check, then strict build, then relevant integration/UI behavior. A function test does not verify a browser, an API route or permissions. A mock model test verifies the request/response boundary, not model intelligence. For a real RAG assistant, evaluate retrieval and answer support separately.</p><p>When checks pass, inspect the diff rather than repeatedly running broader unrelated suites. Repeat checks when a change or unresolved concern justifies them. Record what actually ran and what was not exercised.</p><p><strong>Your exercise:</strong> keep a short diagnostic record for one failing feature candidate: symptom, two plausible causes, evidence that chooses one, correction and rerun result. Include a deliberate fault that a meaningful test catches.</p><p><strong>Done:</strong> explain why each important check exists, show one detected defect and close owned resources so commands terminate. <a href="./review-pr.html">Next: review and PR preparation</a>. Deeper examples: <a href="./verification-and-permissions.html">verification and permissions</a>.</p>',14)])])}const g=t(s,[["render",i]]);export{u as __pageData,g as default};
